public static function eligibility_filter( $result, $flow, $flow_class, $email, $context = array() ) {
		if ( 'refill_due' !== $flow ) {
			return $result;
		}
		$product_id = isset( $context['product_id'] ) ? (int) $context['product_id'] : 0;
		$user_id    = isset( $context['user_id'] ) ? (int) $context['user_id'] : 0;
		$since      = isset( $context['last_purchase_date'] ) ? $context['last_purchase_date'] : '';

		// (a) Klientas jau pirko pakartotinai — laiskas nebeaktualus VISAM ciklui.
		if ( $user_id && $product_id && $since && self::has_repurchased( $user_id, $product_id, $since ) ) {
			return array( 'allowed' => false, 'reason' => 'already_repurchased', 'terminal' => true );
		}

		// (b) Preke laikinai neparduodama — ATIDEDAM, nes bukle gali pasikeisti.
		$p = $product_id ? wc_get_product( $product_id ) : null;
		if ( ! $p || 'publish' !== get_post_status( $product_id ) || ! $p->is_purchasable() ) {
			return array( 'allowed' => false, 'reason' => 'product_inactive', 'terminal' => false );
		}

		return $result;
	}

	/**
	 * S311: ar klientas jau pirko si produkta PO nurodytos datos.
	 * Naudojama tam, kad nesiustume refill laisko zmogui, kuris jau pasipildė.
	 */
	private static function has_repurchased( $user_id, $product_id, $since ) {
		if ( ! $user_id || ! $product_id || ! $since ) {
			return false;
		}
		$orders = wc_get_orders( array(
			'customer_id' => (int) $user_id,
			'status'      => array( 'wc-processing', 'wc-completed', 'wc-on-hold' ),
			'date_created' => '>' . strtotime( $since ),
			'limit'       => 20,
			'return'      => 'objects',
		) );
		foreach ( (array) $orders as $o ) {
			foreach ( $o->get_items() as $item ) {
				$p = $item->get_product();
				if ( $p && (int) $p->get_id() === (int) $product_id ) {
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Sender mirror: PS_REFILL_CANDIDATE + PS_NEXT_REFILL_DATE.
	 */
	private static function mirror_to_sender( $user_id ) {
		if ( ! function_exists( 'ps_esp_adapter' ) ) {
			return;
		}
		$user = get_user_by( 'id', $user_id );
		if ( ! $user ) {
			return;
		}
		global $wpdb;
		// Artimiausia predicted_empty_date (active)
		$nearest = $wpdb->get_var( $wpdb->prepare(
			"SELECT MIN(predicted_empty_date) FROM `" . self::table_name() . "`
			 WHERE user_id = %d AND status = 'active'",
			$user_id
		) );

		$adapter = ps_esp_adapter();
		if ( ! $adapter || ! $adapter->is_configured() ) {
			return;
		}
		$attrs = array(
			'PS_REFILL_CANDIDATE' => $nearest ? 'true' : 'false',
		);
		if ( $nearest ) {
			$attrs['PS_NEXT_REFILL_DATE'] = $nearest;
		}
		$adapter->upsert_contact( $user->user_email, $attrs );
	}
}

